const D = { scale:1, energy:.7, hue:28, speed:1, density:.6, x:.5, y:.92, flick:.6, glow:.6, style:'ember', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const frc=v=>v-Math.floor(v);
const md=(a,n)=>((a%n)+n)%n;
const lrp=(a,b,t)=>a+(b-a)*t;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};

const W=width,Hh=height,u=Math.min(W,Hh);
const H=md(P.hue,360);
const st=P.style;
const ember=st==='ember', sumi=st==='sumi', thermal=st==='thermal', woodcut=st==='woodcut', ascii=st==='ascii';
const en=P.energy*(0.55+0.6*K.intensity);
const cx=P.x*W, cy=P.y*Hh;
const sc=P.scale*(0.9+0.2*K.intensity);
const fh=u*0.30*sc*(0.5+en);
const fw=u*0.16*sc;
const addGlow = ember||thermal;

if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat;
S.lastBeat=K.beat;

function fcol(f){
  if(thermal){ const h=md(H+lrp(40,250,f),360); return [h, lrp(10,90,f), lrp(100,78,f)]; }
  if(sumi){ return [md(H,360), 7, lrp(72,22,f)]; }
  if(woodcut){ return f<0.6? [md(H+8,360),90,96] : [md(H-6,360),95,72]; }
  return [md(H+lrp(22,-14,f),360), lrp(72,96,f), lrp(100,80,f)];
}

// ---- ground glow (additive radial flicker, real-time via K.t) ----
const gr=u*0.5*P.scale*(0.4+P.glow)*(1+0.05*Math.sin(K.t*4));
const gb=0.5+en*0.5+K.swell*0.2+A.bass*0.4;
blendMode(ADD); noStroke();
for(let r=8;r>0;r--){ const t=r/8; fill(md(H+10,360),70,90, 7*gb*(1-t)*(1-t)); ellipse(cx,cy-u*0.01,gr*t*2,gr*t*1.1); }
blendMode(BLEND);

// ---- log teepee ----
push(); translate(cx,cy); noStroke();
const lc = sumi? [md(H,360),6,30] : woodcut? [md(H+15,360),50,40] : [md(H+12,360),55,26];
for(let i=0;i<4;i++){ const a=-0.95+i*0.62; push(); rotate(a);
  fill(lc[0],lc[1],lc[2]); rect(-fw*0.95,-u*0.018,fw*1.9,u*0.05,3);
  fill(lc[0],clp(lc[1]+16,0,100),clp(lc[2]+20,0,100)); ellipse(fw*0.95,-u*0.018+u*0.025,u*0.032,u*0.032);
  if(woodcut){ stroke(0,0,8,70); strokeWeight(Math.max(1,u*0.0016)); noFill(); line(-fw*0.8,-u*0.005,fw*0.7,-u*0.005); noStroke(); }
  pop(); }
pop();

// ---- coals ----
const cg=0.6+K.pulse*0.5*en+A.bass*0.6+0.2*Math.sin(K.t*3);
blendMode(ADD); noStroke();
fill(md(H+5,360),95,90, 40*cg); ellipse(cx,cy,fw*2.2,u*0.05);
fill(md(H+25,360),80,100, 55*cg); ellipse(cx,cy,fw*1.4,u*0.035);
blendMode(BLEND);

// ---- flame tongues (K.t continuous flicker + K.pulse flare) ----
const nT=Math.round(lrp(7,20,clp(P.density,0,1)));
const flare=1+K.pulse*0.28*en+A.bass*0.45;
if(addGlow) blendMode(ADD);
if(ascii) textAlign(CENTER,CENTER);
const glyphs=' .:!*coO#@';
for(let i=0;i<nT;i++){
  const base=fr(i*2+1);
  const bx=cx+(base-0.5)*fw*1.5;
  const ph=fr(i*2+2)*6.2832;
  const spd=0.6+fr(i*2+3)*0.9;
  const fl=0.55+0.45*Math.sin(K.t*(2.0+spd)*P.speed+ph)*(0.5+P.flick*0.8)+0.2*Math.sin(K.t*5.3+ph*2);
  const th=fh*flare*clp(fl,0.2,1.7)*(0.55+0.6*fr(i*2+5));
  const w=fw*(0.5+0.5*fr(i*2+4))*(1-i/nT*0.3);
  const sway=Math.sin(K.t*1.3*P.speed+ph)*fw*0.25*(0.5+en);
  const seg=ascii?9:6;
  for(let s2=0;s2<seg;s2++){
    const f0=s2/seg, f1=(s2+1)/seg, fm=(f0+f1)/2;
    const y0=cy-th*f0, y1=cy-th*f1;
    const w0=w*(1-f0)*(1-f0), w1=w*(1-f1)*(1-f1);
    const xo0=sway*f0, xo1=sway*f1;
    const col=fcol(fm);
    if(ascii){
      const heat=1-fm; const gi=Math.min(glyphs.length-1,Math.floor(heat*(glyphs.length-1)));
      const g=glyphs[gi]; if(g!==' '){ noStroke(); fill(col[0],col[1],col[2], 90*(1-f0*0.3)); textSize(Math.max(4,w*1.6)); text(g,bx+xo0,y0); }
    } else if(woodcut){
      noStroke(); fill(col[0],col[1],col[2]); quad(bx+xo0-w0,y0,bx+xo0+w0,y0,bx+xo1+w1,y1,bx+xo1-w1,y1);
      if(s2%2===0){ stroke(0,0,10,55); strokeWeight(Math.max(0.6,u*0.001)); line(bx+xo0-w0*0.6,y0,bx+xo0+w0*0.6,y0); noStroke(); }
    } else {
      noStroke(); const a=(addGlow?42:88)*(1-f0*0.28); fill(col[0],col[1],col[2],a);
      quad(bx+xo0-w0,y0,bx+xo0+w0,y0,bx+xo1+w1,y1,bx+xo1-w1,y1);
    }
  }
}
blendMode(BLEND);

// ---- embers rising (continuous via K.t, seeded) ----
if(S.emberSeed!==P.seed){ S.emberSeed=P.seed; S.em=[]; for(let i=0;i<80;i++) S.em.push({x:fr(i+10)-0.5,sp:0.4+fr(i+20)*0.9,ph:fr(i+30),sw:0.3+fr(i+40)}); }
const nE=Math.round(80*clp(P.density,0.1,1));
blendMode(ADD); noStroke();
for(let i=0;i<nE;i++){
  const e=S.em[i];
  const life=frc(e.ph+K.t*0.12*e.sp*P.speed);
  const ex=cx+e.x*fw*1.4+Math.sin(K.t*1.5*e.sw+i)*fw*0.5*life;
  const ey=cy-life*fh*1.9;
  const a=(1-life)*(0.5+en)*(thermal?70:90);
  const sz=u*0.004*(0.5+e.sw)*(1-life*0.5);
  const col=ember?[md(H+15,360),80,100]:thermal?[md(H+lrp(40,250,life),360),60,100]:sumi?[md(H,360),6,lrp(70,30,life)]:woodcut?[md(H+10,360),85,95]:[md(H+15,360),80,100];
  fill(col[0],col[1],col[2],a); ellipse(ex,ey,sz,sz);
}
blendMode(BLEND);
